async def act(page):
    """
    Plan:
    1. Navigate to the CMS Pages listing using a relative URL.
    2. Click the "Home Page" link to open the page editor.
    3. Update the "Page Title" field to the requested value using accessibility selectors.
    4. Click the Save button (try common accessible button names).
    """
    # 1) Go to the CMS pages listing (relative URL)
    await page.goto("/index.php/admin/cms_page/")
    await page.wait_for_load_state("networkidle")

    # 2) Open the "Home Page" editor by clicking its link (accessibility selector)
    # Use get_by_role to stay consistent with the accessibility-tree-centric selectors requirement.
    await page.get_by_role("link", name="Home Page").click()
    await page.wait_for_load_state("networkidle")

    # 3) Fill the Page Title field
    new_title = "This is the home page!! Leave here!!"
    # Prefer label-based accessible API. If not present, fall back to the first textbox.
    try:
        await page.get_by_label("Page Title").fill(new_title)
    except Exception:
        # Fallback: fill the first textbox on the page (best-effort using accessibility API)
        await page.get_by_role("textbox").nth(0).fill(new_title)

    # 4) Click Save. Try the most likely accessible button names in order.
    try:
        await page.get_by_role("button", name="Save Page").click()
    except Exception:
        try:
            await page.get_by_role("button", name="Save").click()
        except Exception:
            # As a last attempt, click the first button whose name contains "Save"
            # (use nth() combined with get_by_role to remain accessibility-centric)
            buttons = page.get_by_role("button")
            # iterate to find a button with "Save" in its name
            count = await buttons.count()
            for i in range(count):
                try:
                    name = (await buttons.nth(i).get_attribute("name")) or ""
                except Exception:
                    name = ""
                # get_attribute may not reflect visible label; attempt to click any button with visible text Save
                try:
                    # This will throw if the button's accessible name doesn't match; guard with try
                    await buttons.nth(i).click()
                    break
                except Exception:
                    continue

    # Allow a short pause to let the save complete and UI update
    import asyncio
    await asyncio.sleep(2)

